/**
 * Minimal, dependency-free Markdown → HTML for the subset Malja's own tools
 * emit: headings, paragraphs (single newlines kept as line breaks), **bold**,
 * _italic_, `code`, [links](https://…), bare URLs, > quotes, - lists, ---
 * rules, pipe tables and fenced code blocks.
 *
 * Safety: ALL text is HTML-escaped; only http(s) links become anchors.
 * Fenced ```svg blocks are inlined as live SVG only when the caller marks the
 * markdown as trusted (generated by this server) — otherwise they render as
 * escaped code like every other block.
 */

export interface MarkdownOptions {
  /** Inline ```svg blocks as live SVG (only for server-generated markdown). */
  trustedSvg?: boolean;
  /** Caption shown under a ```mermaid block (rendered as source). */
  mermaidNote?: string;
}

export function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const NUMERIC_CELL = /^\u200E?[+\-−]?[\d٠-٩][\d٠-٩,٬.٫]*%?$/;
/** Years read as labels, not quantities. */
const YEAR_CELL = /^[12٠-٩\d][\d٠-٩]{3}$/;

function isNumeric(cell: string): boolean {
  return NUMERIC_CELL.test(cell) && !YEAR_CELL.test(cell);
}

const ARABIC_LETTER = /[\u0600-\u06FF]/;
const TOKEN = '\\uE000\\d+\\uE000';
const LATIN_RUN = new RegExp(
  `(?:[A-Za-z]|${TOKEN})(?:[A-Za-z0-9 ,.:;/\\-_'&+%]|${TOKEN})*(?:[A-Za-z0-9/]|${TOKEN})`,
  'g',
);
/** Two or more consecutive English words. */
const LATIN_PHRASE = /[A-Za-z]{2,} +[A-Za-z]{2,}/;

/** Inline markup on one line of raw markdown text. */
export function renderInline(raw: string): string {
  const tokens: string[] = [];
  const stash = (html: string): string => `\uE000${tokens.push(html) - 1}\uE000`;

  let text = raw
    .replace(/[\uE000-\uE002]/g, '')
    // Code spans first: their content is literal.
    .replace(/`([^`]+)`/g, (_, code: string) => stash(`<code>${escapeHtml(code)}</code>`))
    // [label](http…) links.
    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, (_, label: string, href: string) =>
      stash(`<a href="${escapeHtml(href)}">${escapeHtml(label)}</a>`),
    )
    // Bare URLs (trailing punctuation / italic markers are not part of the URL).
    .replace(/https?:\/\/[^\s<>()]+/g, (url: string) => {
      const trimmed = url.replace(/[_.,;:!?\]]+$/, '');
      const rest = url.slice(trimmed.length);
      return stash(`<a href="${escapeHtml(trimmed)}">${escapeHtml(trimmed)}</a>`) + rest;
    });

  // In Arabic lines, isolate multi-word English phrases (e.g. an English
  // citation followed by its URL) so the bidi algorithm keeps them in reading
  // order instead of scattering their words across a line wrap.
  if (ARABIC_LETTER.test(text)) {
    text = text.replace(LATIN_RUN, (run) => (LATIN_PHRASE.test(run) ? `\uE001${run}\uE002` : run));
  }

  text = escapeHtml(text)
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/(^|[\s(«])_(?!\s)(.+?)_(?=$|[\s).,;:!?،؛»])/g, '$1<em>$2</em>');

  return text
    .replace(/\uE000(\d+)\uE000/g, (_, i: string) => tokens[Number(i)] ?? '')
    .replace(/\uE001/g, '<span dir="ltr">')
    .replace(/\uE002/g, '</span>');
}

function splitRow(line: string): string[] {
  const inner = line.trim().replace(/^\|/, '').replace(/\|$/, '');
  // Split on pipes not escaped as \|.
  return inner.split(/(?<!\\)\|/).map((cell) => cell.trim().replace(/\\\|/g, '|'));
}

function renderTable(lines: string[]): string {
  const [head, , ...body] = lines;
  const headers = splitRow(head ?? '');
  const bodyRows = body.map(splitRow);
  // A column is numeric when every non-empty body cell is a quantity ("—" = missing).
  const numericColumn = headers.map((_, c) => {
    const cells = bodyRows.map((r) => r[c] ?? '').filter((v) => v !== '' && v !== '—');
    return cells.length > 0 && cells.every(isNumeric);
  });
  const th = headers
    .map((h, c) => `<th${numericColumn[c] ? ' class="num"' : ''}>${renderInline(h)}</th>`)
    .join('');
  const rows = bodyRows
    .map((cells) => {
      const tds = cells
        .map((cell, c) =>
          numericColumn[c] || isNumeric(cell)
            ? `<td class="num">${renderInline(cell)}</td>`
            : `<td>${renderInline(cell)}</td>`,
        )
        .join('');
      return `<tr>${tds}</tr>`;
    })
    .join('\n');
  return `<table>\n<thead><tr>${th}</tr></thead>\n<tbody>\n${rows}\n</tbody>\n</table>`;
}

function renderFence(lang: string, body: string, options: MarkdownOptions): string {
  if (lang === 'svg' && options.trustedSvg && body.trim().startsWith('<svg')) {
    return `<figure class="chart">${body}</figure>`;
  }
  const code = `<pre><code${lang ? ` class="language-${escapeHtml(lang)}"` : ''}>${escapeHtml(body)}</code></pre>`;
  if (lang === 'mermaid' && options.mermaidNote) {
    return `<figure class="mermaid-source">${code}<figcaption>${escapeHtml(options.mermaidNote)}</figcaption></figure>`;
  }
  return code;
}

/** Render a markdown document (the subset described above) to HTML. */
export function markdownToHtml(markdown: string, options: MarkdownOptions = {}): string {
  const lines = markdown.replace(/\r\n?/g, '\n').split('\n');
  const out: string[] = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i]!;

    // Any line opening with ``` starts a fence; the info string's first word
    // (letters, digits, + - _) is the language: ```c++, ```js twoslash, ````.
    const fence = /^(`{3,})\s*([\w+-]*)/.exec(line);
    if (fence) {
      const close = new RegExp(`^\`{${fence[1]!.length},}\\s*$`);
      const body: string[] = [];
      i++;
      while (i < lines.length && !close.test(lines[i]!)) body.push(lines[i++]!);
      i++; // closing fence
      out.push(renderFence(fence[2] ?? '', body.join('\n'), options));
      continue;
    }

    if (line.trim() === '') {
      i++;
      continue;
    }

    const heading = /^(#{1,6})\s+(.*)$/.exec(line);
    if (heading) {
      const level = heading[1]!.length;
      out.push(`<h${level}>${renderInline(heading[2]!)}</h${level}>`);
      i++;
      continue;
    }

    if (/^\s*(---+|\*\*\*+)\s*$/.test(line)) {
      out.push('<hr>');
      i++;
      continue;
    }

    if (line.trim().startsWith('|')) {
      const block: string[] = [];
      while (i < lines.length && lines[i]!.trim().startsWith('|')) block.push(lines[i++]!);
      const isTable = block.length >= 2 && /^\|?\s*:?-{3,}/.test(block[1]!.trim());
      out.push(isTable ? renderTable(block) : `<p>${block.map(renderInline).join('<br>\n')}</p>`);
      continue;
    }

    if (/^>\s?/.test(line)) {
      const block: string[] = [];
      while (i < lines.length && /^>\s?/.test(lines[i]!)) {
        block.push(lines[i++]!.replace(/^>\s?/, ''));
      }
      out.push(`<blockquote><p>${block.map(renderInline).join('<br>\n')}</p></blockquote>`);
      continue;
    }

    if (/^\s*[-*]\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i]!)) {
        items.push(`<li>${renderInline(lines[i++]!.replace(/^\s*[-*]\s+/, ''))}</li>`);
      }
      out.push(`<ul>\n${items.join('\n')}\n</ul>`);
      continue;
    }

    const paragraph: string[] = [];
    while (
      i < lines.length &&
      lines[i]!.trim() !== '' &&
      !/^(#{1,6}\s|```|>|\s*[-*]\s+|\s*\|)/.test(lines[i]!) &&
      !/^\s*(---+|\*\*\*+)\s*$/.test(lines[i]!)
    ) {
      paragraph.push(lines[i++]!);
    }
    // Never stall: a line no block rule claimed is rendered as text.
    if (paragraph.length === 0) paragraph.push(lines[i++]!);
    out.push(`<p>${paragraph.map(renderInline).join('<br>\n')}</p>`);
  }
  return out.join('\n');
}
